// Function delay(ms) — returns new Promise that resolves after ms

// async function greetAfterDelay(name) — await delay, then log greeting

// Call with 'Amara'

questions.solution:
function delay(ms) {
  return new Promise(resolve => {
    setTimeout(resolve, ms);
  });
}

async function greetAfterDelay(name) {
  await delay(1000);
  console.log('Hello, ' + name + '!');
}

greetAfterDelay('Amara');

questions.starter:
// fetchUser(id) — returns Promise, resolve if id > 0, reject otherwise

// async function that calls fetchUser(1) and fetchUser(-1)
// Use try/catch for each, log result or error message

questions.solution:
function fetchUser(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id > 0) {
        resolve({ id, name: 'User ' + id });
      } else {
        reject(new Error('Invalid ID'));
      }
    }, 500);
  });
}

async function main() {
  try {
    const user = await fetchUser(1);
    console.log(user.name);
  } catch (e) {
    console.log(e.message);
  }

  try {
    const user = await fetchUser(-1);
    console.log(user.name);
  } catch (e) {
    console.log(e.message);
  }
}

main();

