questions.starter:
// timeout(ms) — rejects after ms with 'Timeout!'
// slowOperation — resolves in 2000ms with 'Done!'

// Race 1: slow vs timeout(1000) — timeout wins
// Race 2: slow vs timeout(3000) — operation wins

questions.solution:
function timeout(ms) {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error('Timeout!')), ms);
  });
}

function slowOperation() {
  return new Promise(resolve => {
    setTimeout(() => resolve('Done!'), 2000);
  });
}

async function main() {
  try {
    const result1 = await Promise.race([slowOperation(), timeout(1000)]);
    console.log(result1);
  } catch (e) {
    console.log(e.message);
  }

  try {
    const result2 = await Promise.race([slowOperation(), timeout(3000)]);
    console.log(result2);
  } catch (e) {
    console.log(e.message);
  }
}

main();

