// withRetry(asyncFn, maxRetries) — retry on failure

// Test function: fails twice, succeeds on 3rd try
let attempts = 0;
function unreliable() {
  attempts++;
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (attempts < 3) reject(new Error('Fail #' + attempts));
      else resolve('Success on attempt ' + attempts);
    }, 100);
  });
}

// Call withRetry(unreliable, 5) and log the result

questions.solution:
async function withRetry(asyncFn, maxRetries) {
  for (let i = 1; i <= maxRetries; i++) {
    try {
      const result = await asyncFn();
      return result;
    } catch (e) {
      console.log('Attempt ' + i + ' failed: ' + e.message);
      if (i === maxRetries) throw e;
    }
  }
}

let attempts = 0;
function unreliable() {
  attempts++;
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (attempts < 3) reject(new Error('Fail #' + attempts));
      else resolve('Success on attempt ' + attempts);
    }, 100);
  });
}

async function main() {
  try {
    const result = await withRetry(unreliable, 5);
    console.log(result);
  } catch (e) {
    console.log('All retries failed: ' + e.message);
  }
}

main();

questions.starter:
// Fetch user and posts in parallel with Promise.all
// Parse both responses
// Log user name and post count

questions.solution:
async function main() {
  try {
    const [userRes, postsRes] = await Promise.all([
      fetch('https://jsonplaceholder.typicode.com/users/1'),
      fetch('https://jsonplaceholder.typicode.com/posts?userId=1&_limit=3')
    ]);

    if (!userRes.ok || !postsRes.ok) throw new Error('Fetch failed');

    const user = await userRes.json();
    const posts = await postsRes.json();

    console.log(user.name);
    console.log(posts.length);
  } catch (error) {
    console.log('Error: ' + error.message);
  }
}

main();
